code:
import java.util.*;
public class Main {
static void fail() throws java.io.IOException {throw new java.io.IOException();}
public static void main(String[] args) {
fail();
}
}

reference_code:
import java.util.*;
public class Main {
static void fail() throws java.io.IOException {throw new java.io.IOException();}
public static void main(String[] args) {
try{fail();}catch(java.io.IOException e){System.out.println("handled");}
}
}

